function validate([grid]) {
  if (grid.length !== 3 || grid.some(row => row.length !== 3)) return 'grid must be 3 by 3.';
  if (grid.some(row => row.some(v => v < 0 || v > 9))) return 'Each cell holds 0 to 9 stones.';
  if (grid.flat().reduce((a, b) => a + b, 0) !== 9) return 'The grid must hold exactly 9 stones.';
  return null;
}

