function minimumMoves(grid) {
  const extras = [];
  const empties = [];
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      if (grid[r][c] === 0) {
        empties.push([r, c]);
      } else if (grid[r][c] > 1) {
        extras.push([r, c]);
      }
    }
  }
  let best = Infinity;

  function place(index, moves) {
    if (moves >= best) {
      return;
    }
    if (index === empties.length) {
      best = moves;
      return;
    }
    const [row, col] = empties[index];
    for (const [fromRow, fromCol] of extras) {
      if (grid[fromRow][fromCol] > 1) {
        grid[fromRow][fromCol]--;
        place(index + 1, moves + Math.abs(fromRow - row) + Math.abs(fromCol - col));
        grid[fromRow][fromCol]++;
      }
    }
  }

  place(0, 0);
  return best;
}

