function minimumMoves(grid) {
  // List every spare stone by its cell, then try every order of matching spare stones to empty cells.
  const stones = [], holes = [];
  for (let i = 0; i < 9; i++) {
    const count = grid[Math.floor(i / 3)][i % 3];
    if (count === 0) holes.push(i);
    for (let k = 1; k < count; k++) stones.push(i);
  }
  const dist = (a, b) => Math.abs(Math.floor(a / 3) - Math.floor(b / 3)) + Math.abs((a % 3) - (b % 3));
  const used = new Array(stones.length).fill(false);
  let best = Infinity;
  const assign = (j, cost) => {
    if (j === holes.length) { best = Math.min(best, cost); return; }
    for (let s = 0; s < stones.length; s++) {
      if (used[s]) continue;
      used[s] = true;
      assign(j + 1, cost + dist(stones[s], holes[j]));
      used[s] = false;
    }
  };
  assign(0, 0);
  return best;
}

