function generate(rand, size) {
  const grid = [[0, 0, 0], [0, 0, 0], [0, 0, 0]];
  // Fewer occupied cells leave more empty cells to fill, which makes the search larger.
  const cells = size === 'large' ? 1 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 9);
  const pool = [];
  while (pool.length < cells) {
    const cell = Math.floor(rand() * 9);
    if (!pool.includes(cell)) pool.push(cell);
  }
  for (let stone = 0; stone < 9; stone++) {
    const cell = pool[Math.floor(rand() * pool.length)];
    grid[Math.floor(cell / 3)][cell % 3]++;
  }
  return [grid];
}
